      omega: w,
      rpm: w * 30 / Math.PI,
      rpmIdeal: wIdeal * 30 / Math.PI,
      spinEff: w / wIdeal,
      rc_mm: rc * 1e3,
      Nf,
      Lc,
      overlapLayers: Math.min(nL, Math.ceil(Lint / Math.max(pitch, 1e-6))),
      E0,
      Ek,
      Espin,
      Ebear,
      Eheat,
      Ehyst,
      spinPct: Espin / E0 * 100,
