    hits.sort((a, b) => a.err - b.err || a.layers - b.layers);
    const best = hits.slice(0, 5);
    const reachable = vTarget >= vMin - 0.05 && vTarget <= vMax + 0.05;
    const close = best.filter((h) => h.err <= tol);
