    try {
      if (/^https?:\/\//i.test(s) || s.includes("://") || s.startsWith("/") || s.includes("index.html")) {
        const u = new URL(s, location.href);
        s = u.hash.replace(/^#/, "") || u.search.replace(/^\?/, "") || s;
      }
    } catch (_) {
    }
    const mHash = s.match(/(?:^|[&#?])p=([^&#]+)/);
